type BoardEntry = { name: string; score: number };
type LinkedPlayerProfile = { uuid: string; username: string; edition: 'JAVA' | 'BEDROCK'; rank: string; kills: number; deaths: number; playtimeMinutes: number; firstSeen: number; lastSeen: number; balance?: number | null; coins?: number | null };
type AccountStatus = { authenticated: boolean; discord: { id: string; username: string; displayName: string; avatarUrl: string | null } | null; linked: boolean; profile: LinkedPlayerProfile | null };
async function readAccountApiJson<T>(response: Response): Promise<T> {
  const contentType = response.headers.get('content-type') || '';
  if (!contentType.toLowerCase().includes('application/json')) {
    throw new Error('The account API returned a web page instead of JSON. Make sure the Node API is running and your host forwards /api/* requests to it.');
  }
  try { return await response.json() as T; }
  catch { throw new Error('The account API returned an invalid response. Please try again or contact WarNetwork staff.'); }
}
