  const [logoPop, setLogoPop] = useState(0);
  const [discordOnline, setDiscordOnline] = useState<number | null>(null);
  const [modeStatus, setModeStatus] = useState<Record<string, ServerStatus>>({});
  const [serverStatusLoading, setServerStatusLoading] = useState(() => !localStorage.getItem('warnetwork-last-status'));
  const [category, setCategory] = useState('All');
